import{_ as a,c as e,o as s,ag as t}from"./chunks/framework.CQuhCYrb.js";const b=JSON.parse('{"title":"Markdown to MediaWiki Conversion Guide","description":"","frontmatter":{"title":"Markdown to MediaWiki Conversion Guide"},"headers":[],"relativePath":"general/markdown-to-mediawiki-conversion-guide.md","filePath":"general/markdown-to-mediawiki-conversion-guide.md","lastUpdated":null}'),i={name:"general/markdown-to-mediawiki-conversion-guide.md"};function p(d,n,r,l,o,c){return s(),e("div",null,[...n[0]||(n[0]=[t('<h1 id="markdown-to-mediawiki-conversion-guide" tabindex="-1">Markdown to MediaWiki Conversion Guide <a class="header-anchor" href="#markdown-to-mediawiki-conversion-guide" aria-label="Permalink to &quot;Markdown to MediaWiki Conversion Guide&quot;">​</a></h1><h2 id="markdown-to-mediawiki-conversion-guide-1" tabindex="-1">Markdown to MediaWiki Conversion Guide <a class="header-anchor" href="#markdown-to-mediawiki-conversion-guide-1" aria-label="Permalink to &quot;Markdown to MediaWiki Conversion Guide&quot;">​</a></h2><h3 id="convert-markdown-to-mediawiki" tabindex="-1">Convert Markdown to MediaWiki <a class="header-anchor" href="#convert-markdown-to-mediawiki" aria-label="Permalink to &quot;Convert Markdown to MediaWiki&quot;">​</a></h3><p>Mediawiki syntax is a bit different from markdown syntax and GPT tends to prefer markdown syntax and defaults to it even when you ask it to convert to mediawiki.</p><p>This template is a guide to convert markdown to mediawiki syntax using gpt along with regex instructions to do the find and replace what is often missed by gpt.</p><h3 id="exporting-to-intellipedia" tabindex="-1">Exporting to Intellipedia <a class="header-anchor" href="#exporting-to-intellipedia" aria-label="Permalink to &quot;Exporting to Intellipedia&quot;">​</a></h3><p>Intellipedia at every enclave doesn&#39;t allow importing by default. It does however allow you to create pages using the source editor (Edit Source).</p><p>On any pages you want on this wiki or even wikipedia you can view source or edit source and copy the text and paste it into the source editor as a file with extension .txt.</p><p>Transfer that file over to your government computer securely then open the file in notepad or any other text editor and copy the text. Paste that text into the source editor on Intellipedia.</p><table tabindex="0"><thead><tr><th>Title</th><th>Find</th><th>Replace</th><th>Description</th></tr></thead><tbody><tr><td>Bold</td><td><code>\\*\\*(?!\\s)(.*?)(?&lt;!\\s)\\*\\*</code></td><td><code>**$1**</code></td><td>Converts markdown bold to MediaWiki bold</td></tr><tr><td>Heading</td><td><code>=(.*?)=</code></td><td><code>==$1==</code></td><td>Adjusts heading level</td></tr><tr><td>Bullet</td><td><code>^ \\*</code></td><td><code>**</code></td><td>Converts indented bullets to MediaWiki</td></tr><tr><td>Numbering</td><td><code>^\\d(.*?)</code></td><td><code>#</code></td><td>Converts numbered lists</td></tr><tr><td>Italics</td><td><code>\\_(.*?)\\_</code></td><td><code>*$1*</code></td><td>Converts markdown italics</td></tr><tr><td>External Links</td><td><code>\\[(.*?)\\]\\((https?:\\/\\/.*?)\\)</code></td><td><code>[$2 $1]</code></td><td>Converts external links</td></tr><tr><td>Internal Links</td><td><code>\\[(.*?)\\]\\((.*?)\\.md\\)</code></td><td>`[[$2</td><td>$1]]`</td></tr><tr><td>Images</td><td><code>!\\[(.*?)\\]\\((.*?)\\)</code></td><td>`[[File:$2</td><td>alt=$1]]`</td></tr><tr><td>Code Blocks</td><td><code>```(.*?)```</code></td><td><code>&lt;pre&gt;$1&lt;/pre&gt;</code></td><td>Converts code blocks</td></tr><tr><td>Inline Code</td><td><code>`(.*?)`</code></td><td><code>&lt;code&gt;$1&lt;/code&gt;</code></td><td>Converts inline code</td></tr><tr><td>Horizontal Rule</td><td><code>^---$</code></td><td><code>----</code></td><td>Converts horizontal rule</td></tr><tr><td>Level 1 Heading</td><td><code>^# (.*?)$</code></td><td><code>= $1 =</code></td><td>Converts H1 heading</td></tr><tr><td>Level 2 Heading</td><td><code>^## (.*?)$</code></td><td><code>== $1 ==</code></td><td>Converts H2 heading</td></tr><tr><td>Level 3 Heading</td><td><code>^### (.*?)$</code></td><td><code>=== $1 ===</code></td><td>Converts H3 heading</td></tr></tbody></table><h4 id="sed" tabindex="-1">SED <a class="header-anchor" href="#sed" aria-label="Permalink to &quot;SED&quot;">​</a></h4><p>You can do this on a mac or linux machine with sed using the clipboard as input and pipe it through sed and awk commands to get the output using the find and replace commands. echo pbpaste | sed -E &#39;s/**(.<em>?)**/<strong>$1</strong>/g&#39; | sed -E &#39;s/=(.</em>?)=/==$1==/g&#39; | sed -E &#39;s/^ */**/g&#39; | sed -E &#39;s/^\\d(.?)/#/g&#39;</p><h4 id="python" tabindex="-1">Python <a class="header-anchor" href="#python" aria-label="Permalink to &quot;Python&quot;">​</a></h4><h3 id="gpt-prompt-template-markdown-to-mediawiki" tabindex="-1">GPT Prompt Template Markdown to Mediawiki <a class="header-anchor" href="#gpt-prompt-template-markdown-to-mediawiki" aria-label="Permalink to &quot;GPT Prompt Template Markdown to Mediawiki&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span>Please convert the following page into MediaWiki format, adhering to the following guidelines:</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>1. **General Formatting**:</span></span>\n<span class="line"><span>- Remove any &quot;---&quot; separators, as they can interfere with formatting.</span></span>\n<span class="line"><span>- Convert any code blocks to use `` tags for MediaWiki formatting.</span></span>\n<span class="line"><span>- Replace Markdown bold (`**text**`) with MediaWiki bold (`**text**`).</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>2. **Links**:</span></span>\n<span class="line"><span>- Convert Markdown external links `[Text](Link)(http://example.com)` to MediaWiki external links: `[Link Text](http://example.com)` (add a space between the URL and the title).</span></span>\n<span class="line"><span>- Convert Markdown internal links `[Text](Link)(/path/page_title.md)` to MediaWiki internal links: `[Text](Link)(/page-title)`.</span></span>\n<span class="line"><span>- Convert File Links from markddown `![Text](Alt)(http://example.com/image.jpg)` to MediaWiki syntax: `[Text](alt=Alt)(/file-image-jpg)`.</span></span>\n<span class="line"><span>- Remove .md from the end of any internallink.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>3. **Images**:</span></span>\n<span class="line"><span>- Replace Markdown image syntax `![Text](Alt)(http://example.com/image.jpg)` with MediaWiki syntax: `[Text](alt=Alt)(/file-image-jpg)`.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>4. **Lists**:</span></span>\n<span class="line"><span>- Convert unordered lists:</span></span>\n<span class="line"><span>- Replace Markdown `- item` or `* item` with MediaWiki list syntax:</span></span>\n<span class="line"><span>  - `* item`</span></span>\n<span class="line"><span>  - `** subitem`</span></span>\n<span class="line"><span>  - `*** sub-sub-item`</span></span>\n<span class="line"><span>- Convert ordered lists:</span></span>\n<span class="line"><span>- Replace Markdown `1. item` or `2. item` with MediaWiki list syntax:</span></span>\n<span class="line"><span>  - `# item`</span></span>\n<span class="line"><span>  - `## subitem`</span></span>\n<span class="line"><span>  - `### sub-sub-item`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>5. **Tables**:</span></span>\n<span class="line"><span>- Replace Markdown table syntax with MediaWiki table syntax:</span></span>\n<span class="line"><span>- Example Markdown:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br></div></div><p>| Header 1 | Header 2 |</p><p>| Row 1 | Data 1 |</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- Example MediaWiki:</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>| **Header 1 | **Header 2</p><p>| Row 1 | Data 1</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span>6. **References**:</span></span>\n<span class="line"><span>- Add references for any links used on the page. Include them as basic MediaWiki references and ensure a `` tag is added at the bottom of the page.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>7. **Special Characters**:</span></span>\n<span class="line"><span>- Escape any special characters that may conflict with MediaWiki formatting by using `&lt;nowiki&gt;` tags where necessary.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>8. **Categories**:</span></span>\n<span class="line"><span>- Add appropriate categories to the page using MediaWiki category syntax: `[Name](Category:Category)(/category-category-name)`.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>9. **Preservation of Content**:</span></span>\n<span class="line"><span>- Ensure all original content is preserved in meaning and context.</span></span>\n<span class="line"><span>- Maintain the integrity of the original text during conversion.</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>10. **Headers**:</span></span>\n<span class="line"><span>- Convert Markdown headers (`# Header`, `## Subheader`) to MediaWiki headers:</span></span>\n<span class="line"><span>**`== Header ==`</span></span>\n<span class="line"><span>**`=== Subheader ===`</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Apply these instructions to the provided content, ensuring that the final output complies with MediaWiki standards and preserves readability and accuracy.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>[Template]</p>',22)])])}const u=a(i,[["render",p]]);export{b as __pageData,u as default};
